CREATE TABLE IF NOT EXISTS "seller_wallets" ("id" serial PRIMARY KEY NOT NULL, "store_id" integer NOT NULL REFERENCES "stores"("id") ON DELETE CASCADE, "available_kobo" integer DEFAULT 0 NOT NULL, "pending_kobo" integer DEFAULT 0 NOT NULL, "lifetime_earned_kobo" integer DEFAULT 0 NOT NULL, "lifetime_withdrawn_kobo" integer DEFAULT 0 NOT NULL, "debt_kobo" integer DEFAULT 0 NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "seller_wallets_store_uidx" ON "seller_wallets" ("store_id");
CREATE TABLE IF NOT EXISTS "wallet_ledger" ("id" serial PRIMARY KEY NOT NULL, "store_id" integer NOT NULL REFERENCES "stores"("id") ON DELETE CASCADE, "wallet_id" integer NOT NULL REFERENCES "seller_wallets"("id") ON DELETE CASCADE, "entry_type" varchar(40) NOT NULL, "direction" varchar(10) NOT NULL, "amount_kobo" integer NOT NULL, "balance_after_available_kobo" integer NOT NULL, "balance_after_pending_kobo" integer NOT NULL, "order_id" integer REFERENCES "orders"("id") ON DELETE SET NULL, "withdrawal_id" integer, "reference" varchar(160) NOT NULL, "idempotency_key" varchar(160) NOT NULL, "provider_event_id" varchar(160), "metadata" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "wallet_ledger_idempotency_uidx" ON "wallet_ledger" ("idempotency_key");
CREATE UNIQUE INDEX IF NOT EXISTS "wallet_ledger_provider_event_uidx" ON "wallet_ledger" ("provider_event_id");
CREATE INDEX IF NOT EXISTS "wallet_ledger_store_idx" ON "wallet_ledger" ("store_id");
CREATE TABLE IF NOT EXISTS "seller_bank_accounts" ("id" serial PRIMARY KEY NOT NULL, "store_id" integer NOT NULL REFERENCES "stores"("id") ON DELETE CASCADE, "bank_code" varchar(20) NOT NULL, "bank_name" varchar(120) NOT NULL, "account_number_last4" varchar(4) NOT NULL, "account_name" varchar(160) NOT NULL, "recipient_code" varchar(80) NOT NULL, "active" boolean DEFAULT true NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "seller_bank_accounts_store_idx" ON "seller_bank_accounts" ("store_id");
CREATE UNIQUE INDEX IF NOT EXISTS "seller_bank_accounts_recipient_uidx" ON "seller_bank_accounts" ("recipient_code");
CREATE TABLE IF NOT EXISTS "withdrawals" ("id" serial PRIMARY KEY NOT NULL, "store_id" integer NOT NULL REFERENCES "stores"("id") ON DELETE CASCADE, "wallet_id" integer NOT NULL REFERENCES "seller_wallets"("id") ON DELETE CASCADE, "bank_account_id" integer REFERENCES "seller_bank_accounts"("id") ON DELETE SET NULL, "amount_kobo" integer NOT NULL, "fee_kobo" integer DEFAULT 0 NOT NULL, "net_kobo" integer NOT NULL, "status" varchar(20) DEFAULT 'pending' NOT NULL, "reference" varchar(120) NOT NULL, "transfer_code" varchar(80), "recipient_code" varchar(80), "failure_reason" text, "provider_event_id" varchar(160), "created_at" timestamp with time zone DEFAULT now() NOT NULL, "processing_at" timestamp with time zone, "completed_at" timestamp with time zone, "failed_at" timestamp with time zone, "reversed_at" timestamp with time zone, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "withdrawals_reference_uidx" ON "withdrawals" ("reference");
CREATE UNIQUE INDEX IF NOT EXISTS "withdrawals_transfer_code_uidx" ON "withdrawals" ("transfer_code");
CREATE INDEX IF NOT EXISTS "withdrawals_store_idx" ON "withdrawals" ("store_id");
